// 활성 선수 필터
// MVP: 전원 수집 (30명) 또는 tier 기반 필터
// 설정: maxTier를 변경하여 수집 범위 조절
const maxTier = 4; // 1=Tier1만(5명), 2=Tier1-2(16명), 3=Tier1-3(23명), 4=전원(30명)

const players = $input.all().map(item => item.json);
const filtered = players.filter(p => p.tier <= maxTier);

return filtered.map(player => ({ json: player }));

// ============================================
// 대상 선수 선택
// mode에 따라 필터링 전략 변경
// ============================================

// ── 설정 ──────────────────────────────────
// 'manual'       : selectedIds 목록에 있는 선수만 실행
// 'recent_match' : 최근 24시간 내 경기가 있는 선수만 (TODO: FotMob API 연동)
// 'all'          : 전체 통과 (활성 선수 필터 결과 그대로)
const mode = 'manual';

// manual 모드: 실행할 선수 FotMob ID 목록
// 레지스트리의 id 필드와 매칭
const selectedIds = [
  1044299,  // 오현규 (Besiktas)
  828159,   // 김민재 (Bayern Munich)
  940976,   // 이강인 (PSG)
];
// ───────────────────────────────────────────

const players = $input.all().map(item => item.json);

if (mode === 'all') {
  return players.map(p => ({ json: p }));
}

if (mode === 'manual') {
  const idSet = new Set(selectedIds);
  const filtered = players.filter(p => idSet.has(p.id));

  if (filtered.length === 0) {
    throw new Error(
      `선택된 선수가 없습니다. selectedIds: [${selectedIds.join(', ')}]\n` +
      `사용 가능한 ID: ${players.map(p => p.id + '(' + p.nameKr + ')').join(', ')}`
    );
  }

  return filtered.map(p => ({ json: p }));
}

if (mode === 'recent_match') {
  // TODO: FotMob API 연동
  // 각 선수의 최근 경기 일시를 조회하여 24시간 이내인 경우만 통과
  // 구현 예시:
  //
  // const cutoff = new Date();
  // cutoff.setHours(cutoff.getHours() - 24);
  //
  // const results = [];
  // for (const player of players) {
  //   const res = await fetch(`https://www.fotmob.com/api/playerData?id=${player.id}`);
  //   const data = await res.json();
  //   const lastMatch = data.recentMatches?.[0];
  //   if (lastMatch) {
  //     const matchDate = new Date(lastMatch.matchDate);
  //     if (matchDate >= cutoff) {
  //       results.push({ json: { ...player, lastMatch } });
  //     }
  //   }
  //   await new Promise(r => setTimeout(r, 500)); // rate limit
  // }
  // return results.length > 0 ? results : []; // 빈 배열이면 워크플로우 자동 중단

  // 현재는 미구현 → 전체 통과 (fallback)
  console.log('[대상 선수 선택] recent_match 모드 미구현 → 전체 통과');
  return players.map(p => ({ json: p }));
}

throw new Error(`알 수 없는 mode: "${mode}". 사용 가능: manual, recent_match, all`);

// ============================================
// GPT 프롬프트 빌드 (v4 - 실제 스탯 데이터 통합)
// 초회: 수집 데이터 + 스탯 기반 기사 생성
// 재시도: QA 피드백 반영하여 재생성
// ============================================

const input = $input.first().json;

// QA 재시도 감지
const isQaRetry = !!input.qaFeedback;

let player, qaAttempt, qaFeedback;

if (isQaRetry) {
  // QA 통과? False에서 루프백
  player = input.player;
  qaAttempt = (input.qaAttempt || 0) + 1;
  qaFeedback = input.qaFeedback;
} else {
  // 스탯 데이터 병합에서 최초 진입
  player = input;
  qaAttempt = 1;
  qaFeedback = null;
}

const { webSearchSummary, newsSources, redditSources } = player.collected;

// 뉴스 소스 텍스트 생성
const newsSourcesText = newsSources.map((n, i) =>
  `[뉴스${i + 1}] ${n.title}\n  URL: ${n.url}\n  마크다운 링크: [${n.title.split(' - ')[0] || n.title}](${n.url})`
).join('\n');

// Reddit 소스 텍스트 생성
const redditSourcesText = redditSources.map((r, i) =>
  `[Reddit${i + 1}] ${r.title}\n  URL: ${r.url}\n  마크다운 링크: [${r.title}](${r.url})`
).join('\n');

// webSearchSummary를 Reddit/매체로 분리
const fullSummary = webSearchSummary || '';
const mediaSplitMarker = '=== 현지 매체 보도 ===';
let redditSummary = '';
let mediaSummary = '';

if (fullSummary.includes(mediaSplitMarker)) {
  const parts = fullSummary.split(mediaSplitMarker);
  redditSummary = parts[0].replace('=== Reddit 반응 ===', '').trim();
  mediaSummary = parts[1].trim();
} else {
  mediaSummary = fullSummary;
}

const systemPrompt = `너는 한국 축구 전문 AI 기자이다. 해외파 선수에 대한 현지 여론과 뉴스를 분석하여 한국어 기사를 작성한다.

출력 형식은 반드시 아래 JSON 스키마를 따라야 한다:
{
  "title": "기사 제목 (한글, 핵심 수치/반응 포함, 인용 반응 또는 핵심 수치 + 선수명)",
  "subtitle": "부제목 (경기/리그 정보)",
  "summary": "1-2문장 요약 (핵심 수치 + 영문 반응 인용 포함)",
  "content": "마크다운 기사 본문 (3개 섹션: ## 경기 요약, ## 해외 현지 반응 (AI 요약), ## AI 분석 요약)",
  "matchInfo": "리그/대회명 | 경기 스코어",
  "tags": ["선수이름한글", "팀이름한글", ...],
  "evidence": {
    "charts": [
      {
        "id": "고유-kebab-id",
        "title": "차트 제목 (한글)",
        "type": "bar|radar|line|pie",
        "data": [/* 차트 타입에 맞는 데이터 */],
        "dataKeys": ["키1", "키2"],
        "colors": ["#d90828", "#94a3b8"]
      }
    ],
    "dataRows": [
      {
        "label": "지표명 (한글)",
        "value": "수치 또는 텍스트",
        "interpretation": "해석 (한글, 2문장 이상, 30자 이상, 비교/맥락 포함)",
        "source": "출처명 (실제 존재하는 매체/데이터소스)",
        "sourceUrl": "https://출처URL (Reddit/매체 소스인 경우 필수, FotMob/AI 종합 분석은 빈 문자열)"
      }
    ],
    "sources": [
      {
        "url": "https://...",
        "title": "기사/포스트 제목",
        "type": "reddit|news|data"
      }
    ]
  }
}

=== 차트 데이터 구조 규칙 ===
1. bar 차트: data 각 항목에 { name: "항목명(한글)", 키1: 숫자, 키2: 숫자 }
2. radar 차트: data 각 항목에 { stat: "능력명(한글)", value: 0~100 숫자 }
3. line 차트: data 각 항목에 { match/시점키: "라벨", 데이터키: 숫자 }
4. pie 차트: data 각 항목에 { name: "카테고리(한글)", value: 숫자, fill: "#hex색상" }
   - 감성 분석: 긍정(#22c55e), 중립(#94a3b8), 부정(#ef4444) 사용, value 합계 = 100

=== 기사 작성 규칙 ===
1. content는 반드시 3개 섹션: ## 경기 요약, ## 해외 현지 반응 (AI 요약), ## AI 분석 요약
2. 해외 현지 반응 섹션에서 반드시 ### Reddit 반응, ### 현지 매체 하위 섹션을 포함
   - 반드시 수집 데이터의 실제 인용만 사용 (출처 조작 금지)
   - Reddit 데이터가 제공된 경우 반드시 ### Reddit 반응 섹션에 반영
3. evidence.charts: 3-4개, 최소 2종류 이상 차트 타입, 감성 pie chart 필수 포함
4. evidence.dataRows: 4-5개, 각 interpretation 30자 이상, 비교/맥락 포함
5. colors에는 브랜드 컬러 #d90828(빨강)과 #94a3b8(회색) 사용
6. 한글 일관성: 선수명 한글, 영문 정확(FotMob 이름 아닌 실제 표기법 사용)
7. 태그에 반드시 선수한글명, 팀한글명 포함
8. 각 섹션 최소 2문단 이상, content 전체 500자 이상
9. 비축구 콘텐츠 필터링, 다국어 원문 한국어 번역
10. 수집 데이터가 부족하면 무리하게 만들지 말고 있는 정보만으로 작성

=== 축구 용어 규칙 ===
- 한국 축구 팬이 실제 사용하는 외래어/용어를 사용할 것
- 영어 축구 용어를 한글로 직역하지 말 것
- 예시: bicycle kick → "바이시클 킥" (O), "자전거 킥" (X)
- 예시: free kick → "프리킥" (O), "자유 차기" (X)
- 예시: penalty area → "페널티 에어리어" (O), "벌칙 구역" (X)
- 예시: through pass → "스루패스" (O), "관통 패스" (X)
- 예시: corner kick → "코너킥" (O), "모서리 차기" (X)
- 예시: header → "헤딩" (O), "머리공" (X)

=== 해외 현지 반응 작성 규칙 (필수) ===
1. "## 해외 현지 반응 (AI 요약)" 섹션은 반드시 2개 하위 섹션을 포함해야 한다:
   - "### Reddit 반응" — Reddit 팬 여론 데이터 기반, 직접 인용 포함
   - "### 현지 매체" — 현지 매체 보도 데이터 기반, 매체명 명시
2. Reddit 데이터가 제공된 경우 반드시 "### Reddit 반응" 섹션에 반영할 것
3. 각 섹션에서 원문 인용(영어)을 1개 이상 포함할 것

=== 소스 사용 규칙 (필수) ===
1. 현지 매체 보도에서 최소 3개 이상 서로 다른 매체의 기사를 인용할 것
2. 각 매체명을 명시하고 해당 매체의 원문 인용을 포함할 것
3. 제공된 뉴스 소스 중 사용하지 않은 것이 있다면, 가능한 한 모두 활용할 것

=== 출처 링크 작성 규칙 (필수) ===
1. content 마크다운에서 매체명을 언급할 때 반드시 마크다운 링크 형식을 사용할 것:
   - 예: [Türkiye Today](https://turkiyetoday.com/...) → O
   - 예: Türkiye Today는... → X (링크 없이 매체명만 쓰지 말 것)
2. Reddit 게시물/댓글을 인용할 때 해당 포스트 URL을 링크로 포함할 것:
   - 예: [OH amazing goal from a different angle](https://reddit.com/r/soccer/comments/...)
3. 제공된 출처 URL 목록에서 해당하는 URL을 찾아 정확히 사용할 것 (URL을 만들어내지 말 것)
4. 하나의 매체/Reddit 포스트를 여러 번 언급할 때는 최초 언급에만 링크를 포함하면 됨
5. evidence.dataRows의 sourceUrl 필드에도 해당 소스의 URL을 포함할 것
   - Reddit 소스: 해당 Reddit 포스트 URL
   - 매체 소스: 해당 기사 URL
   - FotMob/AI 종합 분석: 빈 문자열 ""
6. evidence.sources 배열에 기사에서 인용한 모든 출처를 포함할 것
7. evidence.sources 배열에 최소 뉴스 3개 + Reddit 3개 출처를 포함할 것
   - 제공된 출처 목록에서 가능한 한 모두 활용
   - 부족 시 제공된 소스를 추가로 인용하여 보충
8. content 본문에서 최소 3개 이상의 서로 다른 매체를 인라인 링크로 인용할 것

=== 데이터 근거(evidence) 작성 규칙 ===

### dataRows 작성 기준 (5~7개)
dataRows는 3가지 유형을 균형있게 포함해야 한다:

1. 여론 기반 (2~3개): 수집된 Reddit/매체 반응에서 도출
   - 예: { label: "팬 반응 키워드", value: "clinical, composed", interpretation: "Reddit에서 다수 언급...", source: "Reddit r/soccer" }
   - 예: { label: "현지 매체 평가", value: "강력한 첫인상", interpretation: "매체에서 평가...", source: "매체명" }

2. 데이터 뒷받침 (2~3개): FotMob 데이터로 여론을 수치적으로 뒷받침
   - 예: { label: "골 전환율", value: "33.33%", interpretation: "팬들이 언급한 clinical finishing을 수치로 뒷받침...", source: "FotMob" }

3. 교차 분석 (1~2개): 여론 + 데이터를 결합한 AI 고유 분석
   - 예: { label: "공격 기여도 종합", value: "상위 10%", interpretation: "매체 평가와 실제 수치를 종합하면...", source: "AI 종합 분석" }

### charts 작성 기준
- sentiment-pie: 수집된 Reddit/매체 반응의 실제 감성 분포 반영
- 최소 1개 차트는 여론 데이터 기반이어야 함
- FotMob 기반 차트는 보조 자료로만 사용

### 핵심 원칙
- FotMob 데이터는 여론을 뒷받침하는 보조 근거로만 사용
- 모든 interpretation은 "왜 이 데이터가 중요한지"를 여론과 연결해서 설명
- source 필드에 실제 출처를 정확히 기재 (Reddit, 매체명, FotMob, AI 종합 분석)

=== 실제 스탯 데이터 활용 규칙 ===
아래에 FotMob 기반 실제 선수 스탯이 제공될 수 있다. 제공된 경우:
1. charts의 bar/radar/line 차트에 실제 수치를 사용할 것 (보조 자료로)
2. dataRows에서 FotMob 데이터는 60% 이하로 유지하고 여론/매체/AI 분석 소스와 균형
3. 데이터를 임의로 만들거나 추측하지 말 것
4. source에 실제 데이터 출처를 명시할 것 (FotMob, Reddit, 매체명, AI 종합 분석)
5. 최근 경기 데이터가 있으면 경기별 성과 bar 차트 생성
6. 포지션별 주요 지표로 radar 차트 생성`;

let userPrompt = `선수: ${player.nameKr} (${player.fotmobName})
팀: ${player.team || '정보없음'}
리그: ${player.league || '정보없음'}

=== Reddit 팬 여론 ===
${redditSummary || '(수집된 Reddit 데이터 없음)'}

=== 현지 매체 보도 ===
${mediaSummary || '(수집된 매체 데이터 없음)'}

=== 출처: 해외 뉴스 (${newsSources.length}건) ===
${newsSourcesText || '(수집된 뉴스 없음)'}

=== 출처: Reddit (${redditSources.length}건) ===
${redditSourcesText || '(수집된 Reddit 반응 없음)'}`;

// ====== 실제 스탯 데이터 추가 ======
if (player.statsData && player.statsData.hasData) {
  const { profile, weeklyStats, recentMatches } = player.statsData;

  userPrompt += '\n\n=== 실제 선수 스탯 데이터 (FotMob 기반) ===';
  userPrompt += '\n아래 데이터는 FotMob에서 수집된 실제 데이터이다. 차트와 dataRows 생성 시 이 데이터를 보조 근거로 활용하되, 여론/매체 데이터와 균형있게 사용할 것.\n';

  if (profile) {
    userPrompt += '\n--- 선수 프로필 ---';
    userPrompt += `\n시장 가치: ${profile.market_value || 'N/A'}`;
    userPrompt += `\n포지션: ${profile.position || 'N/A'}`;
    userPrompt += `\n시즌: ${profile.season || 'N/A'}`;
    userPrompt += `\n출전 경기: ${profile.matches || 'N/A'} (선발: ${profile.started || 'N/A'})`;
    userPrompt += `\n출전 시간: ${profile.minutes_played || 'N/A'}분`;
    userPrompt += `\n골: ${profile.goals || 0} (xG: ${profile.attack_expected_goals || 'N/A'})`;
    userPrompt += `\n어시스트: ${profile.assists || 0} (xA: ${profile.passing_expected_assists || 'N/A'})`;
    userPrompt += `\n평균 평점: ${profile.rating || 'N/A'} (백분위: ${profile.rating_percentile || 'N/A'})`;

    // 포지션별 세부 지표
    const pos = (profile.position || '').toLowerCase();

    if (pos.includes('forward') || pos.includes('striker') || pos.includes('winger') || pos.includes('att')) {
      userPrompt += '\n\n--- 공격 지표 ---';
      userPrompt += `\n슈팅: ${profile.attack_shots || 0} (유효슈팅: ${profile.attack_shots_on_target || 0})`;
      userPrompt += `\n슈팅 정확도: ${profile.attack_shooting_accuracy || 'N/A'}%`;
      userPrompt += `\n골 전환율: ${profile.attack_conversion_rate || 'N/A'}%`;
      userPrompt += `\nxG 차이: ${profile.attack_xg_difference || 'N/A'} (실제골 - xG)`;
      userPrompt += `\n빅찬스 실축: ${profile.attack_big_chances_missed || 0}`;
      userPrompt += `\n드리블 성공: ${profile.attack_dribbles_succeeded || 0} (${profile.attack_dribble_success_rate || 'N/A'}%)`;
      userPrompt += `\n박스 내 터치: ${profile.attack_touches_in_box || 0}`;
    }

