userPrompt += '\n\n위 데이터를 기반으로 기사 JSON을 생성해줘.';

// QA 재시도 시 피드백 추가
if (qaFeedback) {
  userPrompt += `\n\n=== QA 검증 피드백 (${qaAttempt - 1}차 생성 결과) ===
