  },
}];

// ============================================
// 응답 파싱 (v2 - qaAttempt 전달)
// GPT 응답 -> Article 스키마 매핑
// ============================================

const input = $input.first().json;
const { player, systemPrompt, userPrompt, collectedData, qaAttempt } = $('GPT 프롬프트 빌드').first().json;

// GPT 응답 파싱
let gptResponse;
try {
  const rawContent = input.choices[0].message.content;
  gptResponse = JSON.parse(rawContent);
} catch (error) {
  gptResponse = {
    title: `${player.nameKr} 최신 소식`,
    subtitle: '',
    summary: 'GPT 응답 파싱 실패',
    content: '## 경기 요약\n\n정보를 처리하는 중 오류가 발생했습니다.\n\n## 해외 현지 반응 (AI 요약)\n\n-\n\n## AI 분석 요약\n\n-',
    tags: [player.nameKr],
    evidence: { charts: [], dataRows: [] },
  };
}

// Article 스키마로 매핑
const evidence = gptResponse.evidence || { charts: [], dataRows: [] };

const validChartTypes = ['bar', 'radar', 'line', 'pie'];
const charts = (evidence.charts || []).filter(chart =>
  chart.id && chart.title && validChartTypes.includes(chart.type) &&
  Array.isArray(chart.data) && chart.data.length > 0 &&
  Array.isArray(chart.dataKeys) && chart.dataKeys.length > 0 &&
  Array.isArray(chart.colors) && chart.colors.length > 0
).map(chart => ({
  id: chart.id,
  title: chart.title,
  type: chart.type,
  data: chart.data,
  dataKeys: chart.dataKeys,
  colors: chart.colors,
}));

const dataRows = (evidence.dataRows || []).filter(row =>
  row.label && row.value !== undefined && row.interpretation
).map(row => ({
  label: row.label,
  value: row.value,
  interpretation: row.interpretation,
  source: row.source || '',
  sourceUrl: row.sourceUrl || '',
}));

const sources = (evidence.sources || []).filter(src =>
  src.url && src.title
).map(src => ({
  url: src.url,
  title: src.title,
  type: src.type || 'news',
}));

const article = {
  id: `opinion-${player.nameKr}-${Date.now()}`,
  title: gptResponse.title || `${player.nameKr} 최신 소식`,
  subtitle: gptResponse.subtitle || '',
  summary: gptResponse.summary || '',
  content: gptResponse.content || '',
  playerName: player.fotmobName,
  playerNameKr: player.nameKr,
  team: player.team || '',
  league: player.league || '',
  matchInfo: gptResponse.matchInfo || gptResponse.subtitle || '',
  publishedAt: new Date().toISOString(),
  thumbnailUrl: '',
  tags: Array.isArray(gptResponse.tags) ? gptResponse.tags : [player.nameKr],
  evidence: { charts, dataRows, sources },
};

return [{ json: { article, player, systemPrompt, userPrompt, collectedData, qaAttempt } }];

// ============================================
// QA 검증 (v3 - 워크플로우 레벨 재시도 루프 지원)
// 4-Agent QA 검증 → qaPass로 루프/통과 결정
// 실패 시 QA 피드백 포함하여 GPT 프롬프트 빌드로 루프
// ============================================

let { article, player, systemPrompt, userPrompt, collectedData, qaAttempt } = $input.first().json;
qaAttempt = qaAttempt || 1;

const MAX_QA_RETRIES = 3;

// ========== QA Agent 1: DataValidator ==========
function runDataValidator(art) {
  const issues = [];

  for (const row of (art.evidence?.dataRows || [])) {
    if (!row.source || row.source.trim() === '') {
      issues.push({ level: 'warning', msg: `dataRow "${row.label}" 출처 누락` });
    }
  }

  for (const chart of (art.evidence?.charts || [])) {
    if (chart.type === 'pie') {
      const sum = chart.data.reduce((acc, d) => acc + (d.value || 0), 0);
      if (sum !== 100) {
        issues.push({ level: 'critical', msg: `pie chart "${chart.title}" 합계 ${sum} ≠ 100` });
      }
    }
  }

  const sevenDaysAgo = new Date();
  sevenDaysAgo.setDate(sevenDaysAgo.getDate() - 7);
  if (new Date(art.publishedAt) < sevenDaysAgo) {
    issues.push({ level: 'warning', msg: 'publishedAt이 7일 이전' });
  }

  // evidence dataRows 소스 다양성 검증
  const dataRows = art.evidence?.dataRows || [];
  if (dataRows.length > 0) {
    const sources = dataRows.map(r => r.source || '');
    const uniqueSources = new Set(sources.filter(s => s.length > 0));
    const fotmobCount = sources.filter(s => s === 'FotMob').length;
    const fotmobRatio = fotmobCount / sources.length;

    if (fotmobRatio > 0.6) {
      issues.push({
        level: 'critical',
        msg: `dataRows의 ${Math.round(fotmobRatio * 100)}%가 FotMob 단일 소스입니다. 여론/매체/AI 분석 소스를 포함하세요.`,
      });
    }
    if (uniqueSources.size < 3 && dataRows.length >= 4) {
      issues.push({
        level: 'warning',
        msg: `dataRows 소스가 ${uniqueSources.size}종류뿐입니다. 최소 3종류 이상의 소스를 사용하세요.`,
      });
    }
  }

  return issues;
}

// ========== QA Agent 2: KoreanQA ==========
function runKoreanQA(art, playerInfo) {
  const issues = [];
  const content = art.content || '';

  // 축구 용어 사전 검증
  const FOOTBALL_TERMINOLOGY_DICT = {
    '자전거 킥': '바이시클 킥',
    '자전거킥': '바이시클 킥',
    '머리 넣기': '헤딩골',
    '머리공': '헤딩',
    '직접 자유 차기': '직접 프리킥',
    '자유 차기': '프리킥',
    '모서리 차기': '코너킥',
    '불이익 차기': '페널티킥',
    '벌칙 구역': '페널티 에어리어',
    '공 빼앗기': '태클',
    '가위 차기': '시저스 킥',
    '뒤꿈치 차기': '힐킥',
    '발리 차기': '발리슛',
    '장거리 차기': '롱슛',
    '모아 치기': '원투 패스',
    '관통 패스': '스루패스',
    '측면 패스': '크로스',
    '중앙 패스': '센터링',
    '중앙 공격수': '센터 포워드',
    '측면 공격수': '윙어',
    '문지기': '골키퍼',
    '높은 수비선': '하이라인',
    '공 점유율': '점유율',
    '비디오 판독': 'VAR',
  };
  const fullText = `${art.title} ${art.subtitle} ${art.summary} ${content}`;
  const termIssues = [];
  for (const [wrong, correct] of Object.entries(FOOTBALL_TERMINOLOGY_DICT)) {
    if (fullText.includes(wrong)) {
      termIssues.push({ found: wrong, suggested: correct });
    }
  }
  if (termIssues.length > 0) {
    issues.push({
      level: 'critical',
      msg: `부자연스러운 축구 용어: ${termIssues.map(t => '"' + t.found + '" → "' + t.suggested + '"').join(', ')}`,
    });
  }

  const requiredSections = ['## 경기 요약', '## 해외 현지 반응 (AI 요약)', '## AI 분석 요약'];
  for (const sec of requiredSections) {
    if (!content.includes(sec)) {
      issues.push({ level: 'critical', msg: `섹션 누락: ${sec}` });
    }
  }

  if (!content.includes(playerInfo.nameKr) && !art.title.includes(playerInfo.nameKr)) {
    issues.push({ level: 'warning', msg: `선수 한글명 "${playerInfo.nameKr}" 미포함` });
  }

  if (!art.tags || !art.tags.includes(playerInfo.nameKr)) {
    issues.push({ level: 'warning', msg: `태그에 선수한글명 "${playerInfo.nameKr}" 누락` });
  }

  const brokenPattern = /[\ufffd\u0000-\u0008\u000b\u000c\u000e-\u001f]/;
  if (brokenPattern.test(content)) {
    issues.push({ level: 'critical', msg: '인코딩 깨짐 감지' });
  }

  // Reddit/현지 매체 하위 섹션 필수 검증
  if (content.includes('## 해외 현지 반응')) {
    if (!content.includes('### Reddit') && !content.includes('### reddit')) {
      issues.push({
        level: 'critical',
        msg: '"## 해외 현지 반응" 섹션에 "### Reddit 반응" 하위 섹션이 없습니다.',
      });
    }
    if (!content.includes('### 현지 매체')) {
      issues.push({
        level: 'critical',
        msg: '"## 해외 현지 반응" 섹션에 "### 현지 매체" 하위 섹션이 없습니다.',
      });
    }
  }

  return issues;
}

// ========== QA Agent 3: SchemaValidator ==========
function runSchemaValidator(art) {
  const issues = [];

  const requiredFields = ['id', 'title', 'subtitle', 'summary', 'content', 'playerName', 'playerNameKr', 'team', 'league', 'matchInfo', 'publishedAt', 'tags', 'evidence'];
  for (const field of requiredFields) {
    if (art[field] === undefined || art[field] === null) {
      issues.push({ level: 'critical', msg: `필수필드 누락: ${field}` });
    }
  }

  const charts = art.evidence?.charts || [];
  if (charts.length < 1) {
    issues.push({ level: 'critical', msg: 'charts 없음 (최소 1개 필요)' });
  } else if (charts.length > 4) {
    issues.push({ level: 'warning', msg: `charts ${charts.length}개 (권장 1-4개)` });
  }

  for (const chart of charts) {
    if (!chart.id || !chart.title || !chart.type) {
      issues.push({ level: 'critical', msg: '차트 필수필드 누락' });
    }
    if (!Array.isArray(chart.data) || chart.data.length === 0) {
      issues.push({ level: 'critical', msg: `차트 data 비어있음: ${chart.id}` });
    }
    if (chart.type === 'pie') {
      for (const d of (chart.data || [])) {
        if (!d.fill) issues.push({ level: 'warning', msg: `pie 항목 fill 색상 누락: ${d.name}` });
      }
    }
  }

  const dataRows = art.evidence?.dataRows || [];
  if (dataRows.length < 2) {
    issues.push({ level: 'critical', msg: `dataRows ${dataRows.length}개 (최소 2개 필요)` });
  } else if (dataRows.length > 5) {
    issues.push({ level: 'info', msg: `dataRows ${dataRows.length}개 (권장 2-5개)` });
  }

  return issues;
}

// ========== QA Agent 4: QualityReviewer ==========
function runQualityReviewer(art) {
  const issues = [];
  const content = art.content || '';

  if (content.length < 500) {
    issues.push({ level: 'critical', msg: `content 길이 부족: ${content.length}자 (최소 500자)` });
  }

  const sections = content.split(/## /);
  for (const sec of sections.slice(1)) {
    const paragraphs = sec.split('\n\n').filter(p => p.trim().length > 0);
    if (paragraphs.length < 2) {
      const secName = sec.split('\n')[0].trim();
      issues.push({ level: 'warning', msg: `섹션 "${secName}" 문단 부족 (${paragraphs.length}개)` });
    }
  }

  const charts = art.evidence?.charts || [];
  if (!charts.some(c => c.type === 'pie')) {
    issues.push({ level: 'critical', msg: '감성 pie chart 없음' });
  }

  const chartTypes = new Set(charts.map(c => c.type));
  if (chartTypes.size < 2 && charts.length > 0) {
    issues.push({ level: 'warning', msg: `차트 타입 다양성 부족 (${chartTypes.size}종)` });
  }

  const hasKfnRed = charts.some(c => (c.colors || []).includes('#d90828'));
  if (!hasKfnRed && charts.length > 0) {
    issues.push({ level: 'info', msg: '브랜드 컬러 #d90828 미사용' });
  }

  for (const row of (art.evidence?.dataRows || [])) {
    if ((row.interpretation || '').length < 30) {
      issues.push({ level: 'warning', msg: `dataRow "${row.label}" interpretation ${(row.interpretation || '').length}자 (최소 30자)` });
    }
  }

  // 인라인 출처 링크 검증
  const linkPattern = /\[.+?\]\(https?:\/\/.+?\)/g;
  const inlineLinks = (content.match(linkPattern) || []);
  if (inlineLinks.length === 0) {
    issues.push({
      level: 'warning',
      msg: 'content에 인라인 출처 링크가 없습니다. 매체명/Reddit 인용 시 [텍스트](URL) 형식을 사용하세요.',
    });
  }

  // evidence.sources 배열 검증
  const sources = art.evidence?.sources || [];
  if (sources.length === 0) {
    issues.push({
      level: 'warning',
      msg: 'evidence.sources 배열이 비어있습니다. 인용한 출처를 포함하세요.',
    });
  }

  const newsSources = sources.filter(s => s.type === 'news');
  const redditSources = sources.filter(s => s.type === 'reddit');

  if (newsSources.length < 3) {
    issues.push({
      level: 'warning',
      msg: `evidence.sources 뉴스 출처 ${newsSources.length}개 (최소 3개 필요)`,
    });
  }
  if (redditSources.length < 3) {
    issues.push({
      level: 'warning',
      msg: `evidence.sources Reddit 출처 ${redditSources.length}개 (최소 3개 필요)`,
    });
  }

  // 현지 매체 인용 다양성 체크
  const mediaSection = content.split('### 현지 매체')[1]?.split('##')[0] || '';
  if (mediaSection.length > 0) {
    const mediaNames = new Set();
    const mediaPatterns = mediaSection.match(/[A-Z][A-Za-z\s.]+(?=는|에서|의|가|에|도|이)/g);
    if (mediaPatterns) {
      mediaPatterns.forEach(m => mediaNames.add(m.trim()));
    }
    if (mediaNames.size < 3) {
      issues.push({
        level: 'warning',
        msg: `현지 매체 인용이 ${mediaNames.size}개로 부족합니다. 최소 3개 이상의 서로 다른 매체를 인용해주세요.`,
      });
    }
  }

  return issues;
}

// ========== 채점 ==========
function calcScore(issues) {
  let score = 100;
  for (const issue of issues) {
    if (issue.level === 'critical') score -= 30;
    else if (issue.level === 'warning') score -= 10;
    else if (issue.level === 'info') score -= 2;
  }
  return Math.max(0, score);
}

// ========== 자동 수정 ==========
function autoFix(art) {
  for (const chart of (art.evidence?.charts || [])) {
    if (chart.type === 'pie') {
      const sum = chart.data.reduce((acc, d) => acc + (d.value || 0), 0);
      if (sum !== 100 && sum > 0) {
        chart.data = chart.data.map(d => ({ ...d, value: Math.round((d.value / sum) * 100) }));
        const newSum = chart.data.reduce((acc, d) => acc + d.value, 0);
        if (newSum !== 100) chart.data[0].value += (100 - newSum);
      }
    }
  }
  return art;
}

// ========== QA 실행 ==========
article = autoFix(article);

const agents = [
  { name: 'DataValidator', issues: runDataValidator(article) },
  { name: 'KoreanQA', issues: runKoreanQA(article, player) },
  { name: 'SchemaValidator', issues: runSchemaValidator(article) },
  { name: 'QualityReviewer', issues: runQualityReviewer(article) },
];

const allIssues = agents.flatMap(a => a.issues.map(i => ({ ...i, agent: a.name })));
const scores = agents.map(a => ({ name: a.name, score: calcScore(a.issues) }));
const avgScore = scores.reduce((sum, s) => sum + s.score, 0) / scores.length;
const hasCritical = allIssues.some(i => i.level === 'critical');
const passed = !hasCritical && scores.every(s => s.score >= 80) && avgScore >= 80;

// QA 통과 여부 결정: passed이거나 최대 재시도 도달 시 통과
const qaPass = passed || qaAttempt >= MAX_QA_RETRIES;

// QA 피드백 생성 (재시도용)
const qaFeedbackText = allIssues
  .filter(i => i.level === 'critical' || i.level === 'warning')
  .map(i => `[${i.level}][${i.agent}] ${i.msg}`)
  .join('\n');

article._qa = {
  passed,
  attempt: qaAttempt,
  avgScore: Math.round(avgScore),
  scores,
  issues: passed ? [] : allIssues.map(i => `[${i.level}][${i.agent}] ${i.msg}`),
};

return [{
  json: {
    article,
    player,
    collected: player.collected,
    qaFeedback: qaFeedbackText,
    qaAttempt,
    qaPass,
  }
}];

