// === Helper: Responses API 응답에서 텍스트 + annotations 추출 ===
function extractFromResponse(responseJson) {
  let text = '';
  const annotations = [];

  const output = responseJson.output || [];
  for (const item of output) {
    if (item.type === 'message' && item.content) {
      for (const block of item.content) {
        if (block.type === 'output_text') {
          text += (block.text || '') + '\n';
          if (block.annotations) {
            annotations.push(...block.annotations);
          }
        }
      }
    }
  }

  return { text, annotations };
}

// === Reddit AI Agent 결과 파싱 ===
const agentOutput = $('Reddit 결과 변환').first().json;
const redditResult = {
  text: agentOutput.redditAgentResult.text,
  sources: agentOutput.redditAgentResult.sources || [],
};

// === 매체 검색 결과 파싱 (기존 Responses API) ===
const mediaResponse = $('OpenAI 매체 검색').first().json;
const mediaResult = extractFromResponse(mediaResponse);

// === Reddit 소스: agent가 직접 수집한 URL 사용 ===
const redditSources = [];
for (const src of redditResult.sources) {
  if (src.url && !redditSources.some(s => s.url === src.url)) {
    redditSources.push({ url: src.url, title: src.title || '', type: 'reddit' });
  }
}

// === 매체 소스: annotations에서 추출 (비-Reddit URL만) ===
const newsSources = [];
for (const ann of mediaResult.annotations) {
  if (ann.type === 'url_citation' && ann.url) {
    if (!ann.url.includes('reddit.com')) {
      if (!newsSources.some(s => s.url === ann.url)) {
        newsSources.push({ url: ann.url, title: ann.title || '', type: 'news' });
      }
    }
  }
}

// === 이전 accumulated 데이터와 병합 (재시도 시) ===
let mergedNews = [...newsSources];
let mergedReddit = [...redditSources];

if (previousAccumulated) {
  const existingNewsUrls = new Set(mergedNews.map(s => s.url));
  for (const prev of (previousAccumulated.newsSources || [])) {
    if (!existingNewsUrls.has(prev.url)) {
      mergedNews.push(prev);
    }
  }

  const existingRedditUrls = new Set(mergedReddit.map(s => s.url));
  for (const prev of (previousAccumulated.redditSources || [])) {
    if (!existingRedditUrls.has(prev.url)) {
      mergedReddit.push(prev);
    }
  }
}

