const sourcesMet = mergedNews.length >= MIN_NEWS && mergedReddit.length >= MIN_REDDIT;
const meetsThreshold =
  (sourcesMet && attempt >= MIN_ATTEMPTS) ||
  attempt >= MAX_ATTEMPTS;

return [{
  json: {
